isi</th><th>Jurnal terakhir</th><th>Catatan penting terakhir</th></tr></thead><tbody>@foreach($classroomRecap->groupBy('classroom_id') as $rows)<tr><td>{{$rows->first()->classroom->display_name}}</td><td>{{$rows->first()->classroom->homeroom_name}}</td><td>{{$rows->unique(fn($x)=>$x->journal_date->toDateString())->count()}}</td><td>{{$rows->max('journal_date')->translatedFormat('d F Y')}}</td><td>{{$rows->sortByDesc('journal_date')->first()->important_events?:'—'}}</td></tr>@endforeach</tbody></table></section></div><style>@media print{@page{size:A4;margin:15mm}nav,aside,header{display:none!important}body{background:white}}</style></x-app-layout>
